(function() {
    'use strict';

    var button = document.getElementById('post-translate');
    var targetSelect = document.getElementById('post-translate-target');
    var source = document.querySelector('article .markdown-body');
    var status = document.getElementById('translation-msg');
    var postTitleNode = document.querySelector('article h1, header h1, .post-header h1, h1');
    if (!button || !targetSelect || !source || !window.fetch) return;

    var state = 'idle';
    var renderedTarget = '';
    var requestId = 0;
    var activeRequestId = 0;
    var originalBlocks = [];

    /* ---- On-device WASM fallback (transformers.js + opus-mt) ----
     * Used when the server-side providers are rate-limited or down.  The
     * model (~80 MB) downloads once and is cached by the browser. */
    var wasmPipelines = {};
    var wasmUnavailable = {};

    function wasmModelCandidates(src, tgt) {
        return [
            'Xenova/opus-mt-' + src + '-' + tgt,
            'Xenova/opus-mt-tc-big-' + src + '-' + tgt
        ];
    }

    async function getWasmPipeline(src, tgt) {
        var pairKey = src + '|' + tgt;
        if (wasmUnavailable[pairKey]) throw new Error('no wasm model for ' + pairKey);
        if (!wasmPipelines[pairKey]) {
            wasmPipelines[pairKey] = (async function() {
                var mod = await import('https://cdn.jsdelivr.net/npm/@xenova/transformers@2.17.2');
                mod.env.allowLocalModels = false;
                var candidates = wasmModelCandidates(src, tgt);
                var lastError = null;
                for (var i = 0; i < candidates.length; i++) {
                    try {
                        return await mod.pipeline('translation', candidates[i]);
                    } catch (e) {
                        lastError = e;
                    }
                }
                throw lastError || new Error('no wasm model for ' + pairKey);
            })();
            wasmPipelines[pairKey].catch(function() {
                wasmUnavailable[pairKey] = true;
                delete wasmPipelines[pairKey];
            });
        }
        return wasmPipelines[pairKey];
    }

    async function translateChunksWasm(chunks, src, tgt) {
        var pipe = await getWasmPipeline(src, tgt);
        var parts = [];
        for (var i = 0; i < chunks.length; i++) {
            var out = await pipe(chunks[i]);
            parts.push(out && out[0] && out[0].translation_text ? out[0].translation_text : chunks[i]);
        }
        return parts;
    }

    function setState(next) {
        state = next;
        var busy = next === 'loading' || next === 'translating';
        button.disabled = busy;
        targetSelect.disabled = busy;
        button.dataset.translationState = next;
    }

    function setTranslateButtonVisible(visible) {
        button.setAttribute('aria-pressed', String(visible));
        button.setAttribute('aria-label', visible ? 'Show original text' : 'Translate');
        button.title = visible ? 'Show original text' : 'Translate';
    }

    /* --- CWIST WASM/WASI Client Core Kernel (src/utils/client_core.h) --- */
    var __fbWasmCore = (function() {
        var g = typeof window !== 'undefined' ? window : (typeof globalThis !== 'undefined' ? globalThis : this);
        if (g && g.__fbClientCoreWasm) return g.__fbClientCoreWasm;
        var b64 = '';
        var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
        var lookup = new Uint8Array(128);
        for (var i = 0; i < chars.length; i++) lookup[chars.charCodeAt(i)] = i;
        var len = b64.length;
        var pad = b64.charCodeAt(len - 1) === 61 ? (b64.charCodeAt(len - 2) === 61 ? 2 : 1) : 0;
        var bytes = new Uint8Array((len * 3 >> 2) - pad);
        var p = 0;
        for (var j = 0; j < len; j += 4) {
            var n = (lookup[b64.charCodeAt(j)] << 18) |
                    (lookup[b64.charCodeAt(j + 1)] << 12) |
                    (lookup[b64.charCodeAt(j + 2)] << 6) |
                    lookup[b64.charCodeAt(j + 3)];
            bytes[p++] = (n >> 16) & 255;
            if (p < bytes.length) bytes[p++] = (n >> 8) & 255;
            if (p < bytes.length) bytes[p++] = n & 255;
        }
        var inst = new WebAssembly.Instance(new WebAssembly.Module(bytes), {});
        var exp = inst.exports;
        if (exp._initialize) exp._initialize();
        exp.fb_cc_init();
        var cwistView = {
            u8: function(ptr, n) { return new Uint8Array(exp.memory.buffer, ptr, n); },
            i32: function(ptr, n) { return new Int32Array(exp.memory.buffer, ptr, n); },
            f64: function(ptr, n) { return new Float64Array(exp.memory.buffer, ptr, n); }
        };
        var core = {
            exports: exp,
            cwistView: cwistView,
            samplesView: function() { return cwistView.f64(exp.fb_cc_samples_ptr(), exp.fb_cc_samples_len()); },
            outI32: function() { return cwistView.i32(exp.fb_cc_out_i32_ptr(), exp.fb_cc_out_i32_len()); },
            outF64: function() { return cwistView.f64(exp.fb_cc_out_f64_ptr(), exp.fb_cc_out_f64_len()); },
            textIn: function() { return cwistView.u8(exp.fb_cc_text_in_ptr(), exp.fb_cc_text_in_len()); },
            textOut: function() { return cwistView.u8(exp.fb_cc_text_out_ptr(), exp.fb_cc_text_out_len()); },
            chunkIn: function() { return cwistView.u8(exp.fb_cc_chunk_in_ptr(), exp.fb_cc_chunk_in_len()); },
            chunkP0: function() { return cwistView.u8(exp.fb_cc_chunk_p0_ptr(), exp.fb_cc_chunk_p0_len()); },
            chunkP1: function() { return cwistView.u8(exp.fb_cc_chunk_p1_ptr(), exp.fb_cc_chunk_p1_len()); },
            /* Strings cross into WASM as UTF-8.  A string with lone surrogates
               (valid in JS, not in UTF-8) goes as WTF-8 instead so the WASM
               result round-trips it unchanged, exactly like the JS original. */
            lastWtf8: false,
            writeUtf8: function(str) {
                var s = String(str || '');
                var wtf = typeof TextEncoder === 'undefined' ||
                    /[\ud800-\udbff](?![\udc00-\udfff])|(?:^|[^\ud800-\udbff])[\udc00-\udfff]/.test(s);
                core.lastWtf8 = wtf;
                if (!wtf) {
                    var encoded = new TextEncoder().encode(s);
                    /* Grow before taking the view: growth detaches old views. */
                    exp.fb_cc_text_reserve(encoded.length + 1);
                    var dst = core.textIn();
                    dst.set(encoded, 0);
                    dst[encoded.length] = 0;
                    return encoded.length;
                }
                exp.fb_cc_text_reserve(s.length * 3 + 1);
                dst = core.textIn();
                var p = 0;
                for (var i = 0; i < s.length; i++) {
                    var c = s.charCodeAt(i);
                    var c2 = i + 1 < s.length ? s.charCodeAt(i + 1) : 0;
                    if (c < 0x80) {
                        dst[p++] = c;
                    } else if (c < 0x800) {
                        dst[p++] = 0xC0 | (c >> 6);
                        dst[p++] = 0x80 | (c & 0x3F);
                    } else if (c >= 0xD800 && c <= 0xDBFF && c2 >= 0xDC00 && c2 <= 0xDFFF) {
                        var cp = 0x10000 + (((c & 0x3FF) << 10) | (c2 & 0x3FF));
                        i++;
                        dst[p++] = 0xF0 | (cp >> 18);
                        dst[p++] = 0x80 | ((cp >> 12) & 0x3F);
                        dst[p++] = 0x80 | ((cp >> 6) & 0x3F);
                        dst[p++] = 0x80 | (cp & 0x3F);
                    } else {
                        dst[p++] = 0xE0 | (c >> 12);
                        dst[p++] = 0x80 | ((c >> 6) & 0x3F);
                        dst[p++] = 0x80 | (c & 0x3F);
                    }
                }
                dst[p] = 0;
                return p;
            },
            readUtf8: function(len) {
                var src = core.textOut().subarray(0, len);
                if (!core.lastWtf8) {
                    return new TextDecoder().decode(src);
                }
                var out = '';
                var i = 0;
                while (i < len) {
                    var b0 = src[i++];
                    if (b0 < 0x80) {
                        out += String.fromCharCode(b0);
                    } else if ((b0 & 0xE0) === 0xC0) {
                        out += String.fromCharCode(((b0 & 0x1F) << 6) | (src[i++] & 0x3F));
                    } else if ((b0 & 0xF0) === 0xE0) {
                        out += String.fromCharCode(((b0 & 0x0F) << 12) | ((src[i++] & 0x3F) << 6) | (src[i++] & 0x3F));
                    } else {
                        var cp = ((b0 & 0x07) << 18) | ((src[i++] & 0x3F) << 12) | ((src[i++] & 0x3F) << 6) | (src[i++] & 0x3F);
                        cp -= 0x10000;
                        out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
                    }
                }
                return out;
            },
            loadSamples: function(samples) {
                if (!samples || !samples.length) return 0;
                var sv = core.samplesView();
                var n = Math.min(samples.length, 16);
                var start = samples.length - n;
                for (var i = 0; i < n; i++) sv[i] = Number(samples[start + i] || 0);
                return n;
            }
        };
        if (g) g.__fbClientCoreWasm = core;
        return core;
    })();

    var __fbLangCodes = ['en', 'ko', 'ja', 'zh', 'ru', 'ar', 'hi'];

    function detectSourceLanguage(text) {
        var n = __fbWasmCore.writeUtf8(text);
        var idx = __fbWasmCore.exports.fb_cc_detect_source_language(n);
        return __fbLangCodes[idx] || 'en';
    }

    function getTranslatableBlocks() {
        var blocks = [];
        var skipTags = ['pre', 'script', 'style'];

        if (postTitleNode) {
            var titleClone = postTitleNode.cloneNode(true);
            titleClone.querySelectorAll('code, .math-inline, .katex').forEach(function(el) { el.remove(); });
            var titleText = (titleClone.innerText || titleClone.textContent || '').trim();
            if (titleText.length > 0) {
                blocks.push({ element: postTitleNode, originalHtml: postTitleNode.innerHTML, text: titleText });
            }
        }

        function walk(node) {
            if (node.nodeType !== Node.ELEMENT_NODE) return;
            var tag = node.tagName.toLowerCase();
            if (skipTags.indexOf(tag) !== -1 ||
                node.classList.contains('math-block') || node.classList.contains('tikz-block')) {
                return;
            }

            if (/^h[1-6]$/.test(tag) || tag === 'p' || tag === 'li' ||
                tag === 'td' || tag === 'th' || tag === 'caption' ||
                tag === 'summary' || tag === 'figcaption' || tag === 'dt' || tag === 'dd') {
                var clone = node.cloneNode(true);
                clone.querySelectorAll('code, .math-inline, .katex').forEach(function(el) { el.remove(); });
                var text = (clone.innerText || clone.textContent || '').trim();
                if (text.length > 0) {
                    var tocLink = null;
                    if (/^h[1-6]$/.test(tag) && node.id) {
                        tocLink = document.querySelector('.post-toc-list a[href="#' + node.id + '"]');
                    }
                    blocks.push({
                        element: node,
                        originalHtml: node.innerHTML,
                        text: text,
                        tocLink: tocLink,
                        tocLinkHtml: tocLink ? tocLink.innerHTML : ''
                    });
                }
                return;
            }

            node.childNodes.forEach(function(child) {
                walk(child);
            });
        }

        source.childNodes.forEach(function(child) {
            walk(child);
        });

        return blocks;
    }

    function restoreOriginal() {
        originalBlocks.forEach(function(item) {
            item.element.innerHTML = item.originalHtml;
            item.element.style.opacity = '1';
            if (item.tocLink) item.tocLink.innerHTML = item.tocLinkHtml;
        });
    }

    function isInvalidTranslationText(text) {
        if (!text || typeof text !== 'string') return true;
        /* Uppercase in JS so non-ASCII folds (e.g. U+0131, U+017F) match exactly. */
        var n = __fbWasmCore.writeUtf8(text.toUpperCase());
        return __fbWasmCore.exports.fb_cc_is_invalid_translation_text(n) !== 0;
    }

    /* Client memory cache for already translated texts: key is "source|target|text" -> translated text */
    var clientTranslateCache = {};

    function updateTargetOptions(srcLang) {
        var options = targetSelect.options;
        for (var i = 0; i < options.length; i++) {
            var opt = options[i];
            if (opt.value === srcLang) {
                opt.disabled = true;
                opt.hidden = true;
            } else {
                opt.disabled = false;
                opt.hidden = false;
            }
        }
        if (targetSelect.value === srcLang) {
            for (var j = 0; j < options.length; j++) {
                if (!options[j].disabled) {
                    targetSelect.value = options[j].value;
                    break;
                }
            }
        }
    }

    button.addEventListener('click', async function() {
        if (state === 'loading' || state === 'translating') return;
        var target = targetSelect.value;
        if (state === 'rendered' && renderedTarget === target) {
            restoreOriginal();
            renderedTarget = '';
            setTranslateButtonVisible(false);
            setState('idle');
            status.textContent = '';
            return;
        }

        var blocks = getTranslatableBlocks();
        if (blocks.length === 0) {
            status.textContent = 'There is no text to translate.';
            return;
        }

        var fullText = blocks.map(function(b) { return b.text; }).join(' ');
        var sourceLanguage = detectSourceLanguage(fullText);
        updateTargetOptions(sourceLanguage);
        target = targetSelect.value;
        if (sourceLanguage === target) {
            setState('idle');
            status.textContent = 'The post already appears to be in the selected language.';
            setTimeout(function() {
                if (status.textContent === 'The post already appears to be in the selected language.') {
                    status.textContent = '';
                }
            }, 3000);
            return;
        }

        activeRequestId = ++requestId;
        var currentRequestId = activeRequestId;
        setState('translating');
        status.textContent = 'Translating…';

        originalBlocks = blocks;
        blocks.forEach(function(b) {
            b.element.style.opacity = '0.5';
        });

        var controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
        var timeout = controller ? setTimeout(function() { controller.abort(); }, 300000) : null;
        try {
            var batchSize = 12;
            var wasmMode = false;
            for (var i = 0; i < blocks.length; i += batchSize) {
                if (activeRequestId !== currentRequestId) return;
                var batchBlocks = blocks.slice(i, i + batchSize);

                /* Reuse already-translated chunks from client cache */
                var parts = new Array(batchBlocks.length);
                var missingIndices = [];
                var missingChunks = [];

                for (var bIdx = 0; bIdx < batchBlocks.length; bIdx++) {
                    var chunkText = batchBlocks[bIdx].text;
                    var cacheKey = sourceLanguage + '|' + target + '|' + chunkText;
                    if (Object.prototype.hasOwnProperty.call(clientTranslateCache, cacheKey)) {
                        parts[bIdx] = clientTranslateCache[cacheKey];
                    } else {
                        missingIndices.push(bIdx);
                        missingChunks.push(chunkText);
                    }
                }

                if (missingChunks.length > 0) {
                    var fetchedParts = null;
                    var maxAttempts = 8;
                    for (var attempt = 0; attempt < maxAttempts && !fetchedParts; attempt++) {
                        if (activeRequestId !== currentRequestId) return;
                        if (attempt > 0) {
                            status.textContent = 'Retrying translation… (' + (attempt + 1) + '/' + maxAttempts + ')';
                            await new Promise(function(resolve) { setTimeout(resolve, Math.min(1500 * attempt, 8000)); });
                            if (activeRequestId !== currentRequestId) return;
                        }
                        if (!wasmMode) {
                            try {
                                var response = await fetch('/api/translate', {
                                    method: 'POST',
                                    headers: {'Content-Type': 'application/json'},
                                    signal: controller ? controller.signal : undefined,
                                    body: JSON.stringify({source: sourceLanguage, target: target, chunks: missingChunks})
                                });
                                var result = await response.json();
                                if (response.ok && result && result.ok && Array.isArray(result.parts) &&
                                    result.parts.length === missingChunks.length &&
                                    result.parts.every(function(p) { return p && !isInvalidTranslationText(p); })) {
                                    fetchedParts = result.parts;
                                }
                            } catch (serverError) {
                                if (controller && controller.signal.aborted) throw serverError;
                                console.warn('Server translation attempt failed:', serverError);
                            }
                        }
                        if (!fetchedParts && !wasmUnavailable[sourceLanguage + '|' + target]) {
                            try {
                                status.textContent = 'Translating on device…';
                                var wasmParts = await translateChunksWasm(missingChunks, sourceLanguage, target);
                                if (Array.isArray(wasmParts) && wasmParts.length === missingChunks.length &&
                                    wasmParts.every(function(p) { return p && !isInvalidTranslationText(p); })) {
                                    fetchedParts = wasmParts;
                                    wasmMode = true;
                                }
                            } catch (wasmErr) {
                                console.warn('WASM translation attempt failed:', wasmErr);
                            }
                        }
                    }

                    if (!fetchedParts) {
                        throw new Error('All translation backends unavailable after ' + maxAttempts + ' attempts');
                    }

                    for (var mIdx = 0; mIdx < missingIndices.length; mIdx++) {
                        var origIdx = missingIndices[mIdx];
                        var translatedText = (fetchedParts && fetchedParts[mIdx]) ? fetchedParts[mIdx] : missingChunks[mIdx];
                        if (isInvalidTranslationText(translatedText)) {
                            translatedText = missingChunks[mIdx];
                        }
                        parts[origIdx] = translatedText;
                        if (translatedText && translatedText !== missingChunks[mIdx]) {
                            var saveKey = sourceLanguage + '|' + target + '|' + missingChunks[mIdx];
                            clientTranslateCache[saveKey] = translatedText;
                        }
                    }
                }

                if (activeRequestId !== currentRequestId) return;
                for (var j = 0; j < parts.length; j++) {
                    var idx = i + j;
                    if (blocks[idx]) {
                        var targetNode = blocks[idx].element;
                        var finalText = (parts[j] && !isInvalidTranslationText(parts[j])) ? parts[j] : blocks[idx].text;
                        targetNode.textContent = finalText;
                        targetNode.style.opacity = '1';
                        if (blocks[idx].tocLink) blocks[idx].tocLink.textContent = finalText;
                    }
                }
            }

            if (activeRequestId !== currentRequestId) return;
            renderedTarget = target;
            setTranslateButtonVisible(true);
            setState('rendered');
            status.textContent = '';
        } catch (error) {
            console.error('Post translation failed:', error);
            restoreOriginal();
            setState('error');
            status.textContent = 'Translation is temporarily unavailable. Please try again.';
            setTimeout(function() {
                if (state === 'error') {
                    status.textContent = '';
                    setState('idle');
                }
            }, 4000);
        } finally {
            if (timeout) clearTimeout(timeout);
        }
    });

    targetSelect.addEventListener('change', function() {
        if (state !== 'rendered' || targetSelect.value === renderedTarget) return;
        restoreOriginal();
        renderedTarget = '';
        setTranslateButtonVisible(false);
        setState('idle');
        status.textContent = '';
    });

    var firstBlocks = getTranslatableBlocks();
    if (firstBlocks.length > 0) {
        var sampleText = firstBlocks.map(function(b) { return b.text; }).join(' ');
        var detected = detectSourceLanguage(sampleText);
        updateTargetOptions(detected);
        targetSelect.value = detected === 'ko' ? 'en' : 'ko';
    }
    setState('idle');
})();
